def round_div(numerator: int, denominator: int, mode: str = "half_up") -> int:
    """
    Divide two integers and round the quotient to an integer, using exact integer
    arithmetic (no floats). `denominator` must be positive.

    Rounding modes:
      * "half_up"   - round to the nearest integer; exact halves are rounded up (default)
    * "half_even" - round to the nearest integer; exact halves go to the even neighbour
    * "floor"     - round towards negative infinity
    * "ceiling"   - round towards positive infinity

    Raises ValueError if `denominator` <= 0 or `mode` is not one of the names above.

    Examples:
        round_div(7, 2) == 4
        round_div(5, 2, "half_even") == 2
        round_div(-7, 2, "floor") == -4
    """
    if denominator <= 0:
        raise ValueError("denominator must be positive")

    modes = {"half_up", "half_even", "floor", "ceiling"}
    if mode not in modes:
        raise ValueError(f"Invalid mode: {mode}. Must be one of {modes}")

    # Integer division quotient and remainder
    q, r = divmod(numerator, denominator)

    if mode == "floor":
        return q

    if mode == "ceiling":
        if r == 0:
            return q
        return q + 1

    # For half_up and half_even, we need to handle the remainder
    # r is always 0 <= r < denominator because denominator > 0
    # The exact fraction is q + r/denominator
    # The distance to the next integer is (denominator - r) / denominator
    # The distance to the current integer is r / denominator

    # If r is 0, it's an exact division
    if r == 0:
        return q

    # Check if it's exactly a half
    is_half = (2 * r == denominator)

    if is_half:
        if mode == "half_up":
            # Symmetric around zero: -2.5 -> -3, 2.5 -> 3
            # This is equivalent to rounding away from zero
            return q + (1 if numerator > 0 else -1)
        elif mode == "half_even":
            # Round to the nearest even integer
            if q % 2 == 0:
                return q
            else:
                return q + (1 if numerator > 0 else -1)
    else:
        # Not a half, just round to nearest
        # If r/denominator < 0.5, round to q
        # If r/denominator > 0.5, round to q + 1
        if 2 * r < denominator:
            return q
        else:
            return q + 1

    # This part should technically be unreachable given the logic above,
    # but we'll return q as a fallback.
    return q
